#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <limits.h>
#include <errno.h>

/* Test-host adaptation only: this sandbox has no writable /tmp. */
FILE *tmpfile(void) {
    const char *root = getenv("ICSTUDIO_TEST_TMPDIR");
    char path[PATH_MAX];
    if (!root || snprintf(path, sizeof(path), "%s/ngspice-XXXXXX", root) >= (int)sizeof(path)) {
        errno = EINVAL; return NULL;
    }
    int fd = mkstemp(path);
    if (fd < 0) return NULL;
    unlink(path);
    FILE *stream = fdopen(fd, "w+");
    if (!stream) close(fd);
    return stream;
}
FILE *tmpfile64(void) { return tmpfile(); }
